## Submitted testbench
```systemverilog
module tb;

  // ------------------------------------------------------------
  // Parameters
  // ------------------------------------------------------------
  localparam int CLK_PERIOD   = 8;          // 125 MHz clock
  localparam int PRESCALE_VAL = 16'd1;      // prescale input to uart_tx

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  reg clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  reg rst = 0;

  // ------------------------------------------------------------
  // AXI‑Stream interface signals
  // ------------------------------------------------------------
  reg  [7:0] s_axis_tdata;
  reg        s_axis_tvalid;

  wire       txd;
  wire       busy;
  wire       s_axis_tready;
  reg  [15:0] prescale_val = PRESCALE_VAL;  // connect to DUT

  // ------------------------------------------------------------
  // DUT instantiation (uart_tx, default DATA_WIDTH = 8)
  // ------------------------------------------------------------
  uart_tx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd          (txd),
    .busy         (busy),
    .prescale     (prescale_val)
  );

  // ------------------------------------------------------------
  // Reset sequencing
  // ------------------------------------------------------------
  initial begin
    rst = 1;
    @(posedge clk);
    rst = 1;
    @(posedge clk);
    rst = 0;
    @(posedge clk);
    rst = 0;
    @(posedge clk);
  end

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Allow design to settle after reset
    repeat (10) @(posedge clk);

    // ----------------------------------------------------------------
    // Wait until the AXI‑Stream interface is idle (s_axis_tready = 1)
    // ----------------------------------------------------------------
    wait (s_axis_tready);
    @(posedge clk);

    // ----------------------------------------------------------------
    // First transaction: load byte 0xC3
    // ----------------------------------------------------------------
    s_axis_tvalid = 1'b1;
    s_axis_tdata  = 8'hC3;
    @(posedge clk);
    s_axis_tvalid = 1'b0;   // handshake completed, de‑assert tvalid

    // ----------------------------------------------------------------
    // Wait for the transmitter to finish and become ready again
    // ----------------------------------------------------------------
    wait (s_axis_tready);
    @(posedge clk);

    // ----------------------------------------------------------------
    // Second transaction: load byte 0x3C (the byte that must end up as 8'h3C)
    // ----------------------------------------------------------------
    s_axis_tvalid = 1'b1;
    s_axis_tdata  = 8'h3C;
    @(posedge clk);
    s_axis_tvalid = 1'b0;

    // ----------------------------------------------------------------
    // Give the design enough time to finish transmitting the second byte,
    // shift out its 8 data bits, and satisfy the T6 coverage condition.
    // With prescale = 1 the whole frame finishes well before 500 clocks.
    // ----------------------------------------------------------------
    repeat (500) @(posedge clk);

    // ----------------------------------------------------------------
    // Coverage point T6_tvalid_rise_on_frame_end has been hit – end simulation.
    // ----------------------------------------------------------------
    $finish;
  end

endmodule
```

